// CPU Performance Metrics & Timing
typedef long long Instruction_Count; // IC
typedef float CPI_Ratio;           // CPI
typedef float Clock_Freq_Hz;       // F

// Clock Cycle Time (Tc) = 1 / F
const Clock_Freq_Hz F_Ghz = 3.0f;
const float Tc_seconds = 1.0f / (F_Ghz * 1e9);

// Average Cycles Per Instruction
const CPI_Ratio Average_CPI = 1.2f;

// Total Execution Time (T)
// T = IC * CPI * Tc
Instruction_Count IC = 5000000000;

float Execution_Time_s = IC * Average_CPI * Tc_seconds;

// Alternative definition: T = (IC * CPI) / F
float T_alt_s = (IC * Average_CPI) / (F_Ghz * 1e9);
